    counts: proxy.counts,
    waitForHeldGet: proxy.waitForHeldGet,
    releaseGet: proxy.releaseGet,
    corruptStore: backend.corruptStore,
    async stop() {
      await proxy.close();
      await backend.stop();
      backend.cleanup();
    },
  };
}

